import json
from pathlib import Path
import numpy as np
from PIL import Image
from scipy import ndimage as ndi
ROOT=Path(__file__).parent
OUT=ROOT/'predictions.json'
def save(n,series):
 p=json.loads(OUT.read_text());p[f'fig_{n:02}.png']=series
 OUT.write_text(json.dumps(p,ensure_ascii=False,indent=2))
 print(f'fig_{n:02}: '+', '.join(f'{s[\"name\"]}: {len(s[\"data\"])}' for s in series))
def s(name,points):
 return {'name':name,'data':[{'x':round(float(x),6),'y':round(float(y),6)} for x,y in points]}
def px(points,xt,yt,logx=False,logy=False):
 def conv(v,t,log):
  a,b,c,d=t
  if log:c,d=np.log10([c,d])
  z=c+(v-a)*(d-c)/(b-a)
  return 10**z if log else z
 return [(conv(x,xt,logx),conv(y,yt,logy)) for x,y in points]
def arr(n):return np.array(Image.open(ROOT/f'images/fig_{n:02}.png').convert('RGB')).astype(float)
def cc(mask,box=None,minimum=3,maximum=1000):
 mask=mask.copy()
 if box:
  x0,y0,x1,y1=box
  keep=np.zeros_like(mask);keep[y0:y1,x0:x1]=1;mask &= keep
 lab,num=ndi.label(mask)
 out=[]
 for i in range(1,num+1):
  yy,xx=np.where(lab==i);area=len(xx)
  if minimum<=area<=maximum:out.append((float(xx.mean()),float(yy.mean()),area,int(xx.max()-xx.min()+1),int(yy.max()-yy.min()+1)))
 return sorted(out)
